// Import the Verus prelude for Vec and verification constructs.
use verus::prelude::*;

verus! {

    /// Given a non‐empty Vec of chars `a`, returns a new Vec `b` which is the exact reverse of `a`.
    /// 
    /// Specification:
    ///   - requires: `a.len() > 0`
    ///   - ensures:  `b.len() == a.len()`
    ///   - ensures:  for all valid indices `i` in `[0, a.len())`,
    ///               `b[i] == a[a.len() - 1 - i]`
    fn reverse(a: Vec<char>) -> Vec<char> {
        // Precondition: input must be nonempty
        requires(a.len() > 0);
        // Postconditions: output has same length, and is the reverse of `a`
        ensures(|b: Vec<char>| 
            b.len() == a.len() &&
            forall(|i: usize| i < a.len() ==> b[i] == a[a.len() - 1 - i])
        );

        let mut b: Vec<char> = Vec::new();
        let n = a.len();
        let mut i: usize = 0;

        // Loop to build `b` by pushing elements from the end of `a` towards the front.
        while i < n {
            // Invariants needed for verification:
            // 1. i never exceeds n
            // 2. b.len() always equals i
            // 3. For all j < i, b[j] == a[n - 1 - j]
            invariant(i <= n);
            invariant(b.len() == i);
            invariant(forall(|j: usize| j < i ==> b[j] == a[n - 1 - j]));
            // Decreases clause to guarantee termination
            decreases(n - i);

            // Push the (n-1-i)-th character of `a` onto the end of `b`.
            let c = a[n - 1 - i];
            b.push(c);
            i += 1;
        }

        b
    }
}